signature.code:
type UseMutateOptions<
  Data = any,
  Err = Error,
  Args extends any[] = []
> = {
  onSuccess?: (data: Data, args: Args) => void;
  onError?: (error: Err, args: Args) => void;
  onSettled?: (data: Data | undefined, error: Err | undefined, args: Args) => void;
  queryKey?: QueryKey;
}

examples.code:
const options: UseMutateOptions<Todo, Error, [CreateTodoInput]> = {
  onSuccess: (data) => {
    console.log('Created todo:', data.id);
  },
};

const options: UseMutateOptions<Todo, Error, [string, UpdateInput]> = {
  onSuccess: (data, [id, input]) => {
    console.log(`Updated ${id}:`, data);
  },
  onError: (error, [id]) => {
    console.error(`Failed to update ${id}:`, error.message);
  },
  onSettled: (data, error, [id]) => {
    console.log(`Mutation for ${id} completed`);
  },
  queryKey: ['todos'], // Invalidate todos query
};
